const results = [];

// 1. Loop satu-satu row hasil baca Google Sheets (yang udah difilter status SENT/FU1 di node sebelumnya)
for (const item of $input.all()) {
  const data = item.json;
  let category = null; // nanti diisi 'KIRIM FU1' / 'KIRIM FU2' / dibiarin null kalau belum waktunya

  // 2. Cabang buat lead yang statusnya masih SENT (belum pernah di-follow-up)
  if (data.status === 'SENT') {
    const sentDate = DateTime.fromFormat(data.Sent_Date, 'd/M/yyyy');

    // 2a. Guard: kalau Sent_Date gagal dibaca (format aneh/kosong) -> jangan diproses diam-diam,
    //     masukin ke results sebagai baris ANOMALI biar tetep muncul di digest buat dicek manual
    if (!sentDate.isValid) {
      results.push({
        json: {
          ...data,
          category: 'ANOMALI',
          DraftMsg: `⚠️ *${data.nama}* (${data.ID}) — Sent_Date ga kebaca ("${data.Sent_Date}"). Cek manual di sheet.\n-----------------------------------`,
        },
      });
      continue; // lanjut ke row berikutnya, row ini udah selesai diproses
    }

    // 2b. Cek threshold H+2: kalau Sent_Date udah lewat 2 hari dari sekarang -> tandain butuh FU1
    if (sentDate.toMillis() < $now.minus({ days: 2 }).toMillis()) {
      category = 'KIRIM FU1';
    }

  // 3. Cabang buat lead yang statusnya udah FU1 (pernah di-follow-up sekali)
  } else if (data.status === 'FU1') {
    const fu1Date = DateTime.fromFormat(data.FU1_Date, 'd/M/yyyy');
    const sentDate = DateTime.fromFormat(data.Sent_Date, 'd/M/yyyy');

    // 3a. Guard: FU1_Date gagal dibaca -> ANOMALI, jangan diproses diam-diam
    if (!fu1Date.isValid) {
      results.push({
        json: {
          ...data,
          category: 'ANOMALI',
          DraftMsg: `⚠️ *${data.nama}* (${data.ID}) — FU1_Date ga kebaca ("${data.FU1_Date}"). Cek manual di sheet.\n-----------------------------------`,
        },
      });
      continue;
    }

    // 3b. Guard: FU1_Date ga boleh lebih awal dari Sent_Date (logically ga mungkin) -> ANOMALI
    if (sentDate.isValid && fu1Date.toMillis() < sentDate.toMillis()) {
      results.push({
        json: {
          ...data,
          category: 'ANOMALI',
          DraftMsg: `⚠️ *${data.nama}* (${data.ID}) — FU1_Date (${data.FU1_Date}) lebih awal dari Sent_Date (${data.Sent_Date}). Cek manual di sheet.\n-----------------------------------`,
        },
      });
      continue;
    }

    // 3c. Cek threshold H+5: kalau FU1_Date udah lewat 5 hari dari sekarang -> tandain butuh FU2
    if (fu1Date.toMillis() < $now.minus({ days: 5 }).toMillis()) {
      category = 'KIRIM FU2';
    }
  }

  // 4. Kalau category masih null di titik ini artinya: belum waktunya kirim,
  //    ATAU statusnya di luar SENT/FU1 (harusnya udah kefilter di Sheets node duluan) -> skip, ga usah masuk digest
  if (!category) continue;

  // 5. Siapin dua template pesan (persis sama kayak Set node FU1msg/FU2msg yang lama)
  const templateFU1 = `Halo kak ${data.nama}, mau follow up pesan sebelumnya soal penawaran video. Kalau kemarin lagi sibuk atau kelewat, gapapa banget kak 😄 Kalau ada yang mau ditanyain soal videonya/prosesnya, aku siap bantu jelasin lebih detail.`;
  const templateFU2 = `Halo kak, mau closing aja ya — kalau saat ini emang belum pas waktunya atau belum butuh, aku paham banget kok 🙏 Kalau nanti kepikiran atau butuh, tinggal chat aja ya, aku available. Makasih banyak udah baca pesan aku sebelumnya!`;

  // 6. Pilih template & label sesuai category yang kena di step 2b / 3c
  const label = category === 'KIRIM FU1' ? 'FU1' : 'FU2';
  const template = category === 'KIRIM FU1' ? templateFU1 : templateFU2;

  // 7. Rakit draft pesan final (format yang bakal muncul di Slack digest)
  const DraftMsg = `🏢 *${data.nama}* (${data.niche})\n📲 WA: ${data['No WA']}\n💬 *Draft ${label}:*\n${template}\n-----------------------------------`;

  // 8. Masukin row ini ke hasil akhir yang bakal diteruskan ke Aggregate -> Notif
  results.push({
    json: {
      ...data,
      category,
      DraftMsg,
    },
  });
}

// 9. Balikin semua item (draft FU1/FU2 + anomali) sebagai output node ini
return results;
